Contract ProcessSaleService::makeCashPayment(amount:Real): Boolean {

            precondition:
          not CurrentSale.oclIsUndefined() and not CurrentSale.IsComplete = true and CurrentSale.IsReadytoPay = true and amount >= CurrentSale.Amount

            postcondition:
          let payment:CashPayment in payment.oclIsNew() and payment.AmountTendered = amount and payment.Balance = amount - CurrentSale.Amount and CurrentSale.AssoicatedPayment = payment and CurrentSale.Belongedstore = self.CurrentStore and self.CurrentStore.Sales->includes(CurrentSale) and CurrentSale.IsComplete = true and CurrentSale.Time = ThirdPartyServices.now() and ThirdPartyServices.save(payment) and result = true

        }
